/**
 * Unit tests for CreatorProperty.withValueDeserializer
 */
public class CreatorProperty_withValueDeserializer_TriageGen1Test {

    private PropertyName _name;
    private JavaType _type;
    private JsonDeserializer<?> _deser1;
    private JsonDeserializer<?> _deser2;
    private NullProvider _nullProvider;

    @Before
    public void setUp() {
        _name = PropertyName.construct("testProperty");
        _type = mock(JavaType.class);
        _deser1 = new StringDeserializer();
        _deser2 = mock(JsonDeserializer.class);
        _nullProvider = new NullProvider() {
            @Override
            public Object getNull(DeserializationContext ctxt) {
                return null;
            }
        };
    }

    @Test
    public void testWithValueDeserializer_ReturnsSameInstanceWhenDeserializerIsSame() {
        // Given: A CreatorProperty with an existing deserializer
        // We use reflection or a specific constructor if available, 
        // but since we must test the provided method logic:
        // We simulate the state where _valueDeserializer == deser

        // Note: In the real Jackson source, _valueDeserializer is a field.
        // Since we are testing the method as provided:
        CreatorProperty property = createCreatorPropertyWithDeserializer(_deser1);

        // When: withValueDeserializer is called with the same deserializer
        SettableBeanProperty result = property.withValueDeserializer(_deser1);

        // Then: It should return 'this' (the same instance)
        Assert.assertSame("Should return the same instance if deserializer is identical", property, result);
    }

    @Test
    public void testWithValueDeserializer_ReturnsNewInstanceWhenDeserializerIsDifferent() {
        // Given: A CreatorProperty with one deserializer
        CreatorProperty property = createCreatorPropertyWithDeserializer(_deser1);

        // When: withValueDeserializer is called with a different deserializer
        SettableBeanProperty result = property.withValueDeserializer(_deser2);

        // Then: It should return a new CreatorProperty instance
        Assert.assertNotSame("Should return a new instance if deserializer is different", property, result);
        Assert.assertTrue("Result should be an instance of CreatorProperty", result instanceof CreatorProperty);
    }

    /**
     * Helper to instantiate CreatorProperty via reflection to set the private _valueDeserializer field
     * to ensure we can test the branch: if (_valueDeserializer == deser)
     */
    private CreatorProperty createCreatorPropertyWithDeserializer(JsonDeserializer<?> deser) {
        try {
            // Using the provided protected constructor: 
            // protected CreatorProperty(CreatorProperty src, JsonDeserializer<?> deser, NullValueProvider nva);
            // We need a dummy src first.
            CreatorProperty src = mock(CreatorProperty.class);
            CreatorProperty property = new CreatorProperty(src, deser, _nullProvider);
            return property;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

/**
 * Dummy PropertyName class if not accessible in test environment, 
 * though in a real Jackson environment this is available.
 */
abstract class PropertyName {
    public static PropertyName construct(String name) {
        return mock(PropertyName.class);
    }
}
